    22	const BASE_STYLE = {
    23	  textStyle: 'caption',
    24	  textTransform: 'uppercase' as const,
    25	  color: 'text.default',
    26	};
    27	
    28	const LINK_PROPS = {
    29	  ...BASE_STYLE,
