    31	  _hover: { opacity: 0.6 },
    32	  sx: {
    33	    transition: 'opacity var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard)',
    34	  },
    35	};
    36	
    37	const Separator = () => (
    38	  <Text as="span" aria-hidden="true" {...BASE_STYLE} mx="2xs">
    39	    /
    40	  </Text>
    41	);
    42	
    43	/**
    44	 * PDP breadcrumb reflecting the product's category path.
    45	 * HOME is always the first crumb; currentPage is the non-link terminal item.
    46	 */
    47	const Breadcrumb = ({ categories, currentPage }: BreadcrumbProps) => {
    48	  const hasMoreAfterHome = categories.length > 0 || Boolean(currentPage);
    49	
    50	  return (
    51	    <Box as="nav" aria-label="Breadcrumb">
    52	      <Box as="ol" listStyleType="none" m={0} p={0} sx={{ paddingInlineStart: 0 }}>
    53	        <Box as="li" display="inline">
    54	          <Text as={RouteLink} to="/" {...LINK_PROPS}>
    55	            Home
    56	          </Text>
    57	          {hasMoreAfterHome && <Separator />}
    58	        </Box>
    59	
    60	        {categories.map((category, index) => {
    61	          const isLastCrumb = index === categories.length - 1 && !currentPage;
    62	          return (
    63	            <Box as="li" key={category.id} display="inline">
    64	              <Text as={RouteLink} to={categoryUrlBuilder(category)} {...LINK_PROPS}>
    65	                {category.name}
    66	              </Text>
    67	              {!isLastCrumb && <Separator />}
    68	            </Box>
    69	          );
    70	        })}
    71	
    72	        {currentPage && (
    73	          <Box as="li" display={{ base: 'block', md: 'inline' }}>
