     1	import React from 'react';
     2	import { Link as RouteLink } from 'react-router-dom';
     3	import { Box, Text } from '@salesforce/retail-react-app/app/components/shared/ui';
     4	
     5	type PageToolbarVariant = 'breadcrumbs' | 'recently-viewed' | 'section-title';
     6	
     7	type ZimmPageToolbarProps =
     8	  | { variant: 'breadcrumbs'; children?: React.ReactNode }
     9	  | {
    10	      variant: 'recently-viewed' | 'section-title';
    11	      /** Section or list heading. */
    12	      heading: string;
    13	      /** CTA label shown to the right of the heading. */
    14	      linkText?: string;
    15	      /** CTA destination. */
    16	      linkHref?: string;
    17	    };
    18	
    19	// Per-variant padding. '2xl' and '3xl' are the named spacing keys behind
    20	// --zimm-scale-800 (32px) and --zimm-scale-1000 (40px) — see
    21	// foundation/zimmTokens.ts, which defines both aliases from those keys. Using the
    22	// semantic keys keeps this at level 2 of the overrideStyling.md hierarchy rather
    23	// than reaching for the numeric vars.
    24	//
    25	// Keyed per variant because all three treatments share one wrapper: breadcrumbs
    26	// needs a 40px right inset where the other two keep 80px, so a single shared value
    27	// can no longer express every side.
    28	const PADDING = {
    29	  // Breadcrumbs: 40px horizontal, 32px vertical.
    30	  breadcrumbs: { pt: '2xl', pb: '2xl', pl: '3xl', pr: '3xl' },
    31	  'recently-viewed': { pt: 'xs', pb: '2xl', pl: '3xl', pr: '5xl' },
    32	  'section-title': { pt: 'xs', pb: '2xl', pl: '3xl', pr: '5xl' },
    33	} satisfies Record<PageToolbarVariant, { pt: string; pb: string; pl: string; pr: string }>;
    34	
    35	/**
    36	 * Structural wrapper for breadcrumb, recently-viewed, and section-title treatments.
    37	 * Port of the handover `zimm-page-toolbar` element.
    38	 */
    39	const ZimmPageToolbar = (props: ZimmPageToolbarProps) => {
    40	  return (
    41	    <Box {...PADDING[props.variant]} backgroundColor="background.07">
    42	      {props.variant === 'recently-viewed' || props.variant === 'section-title' ? (
    43	        <Box display="flex" alignItems="center" justifyContent="space-between" width="100%">
    44	          <Text as="h2" textStyle="heading3" color="text.default" m={0}>
    45	            {props.heading}
    46	          </Text>
    47	          {props.linkText && props.linkHref && (
    48	            <Text
    49	              as={RouteLink}
    50	              to={props.linkHref}
    51	              textStyle="linkLg"
    52	              color="text.default"
    53	              textDecoration="none"
    54	              _hover={{ color: 'text.secondary', textDecoration: 'none', opacity: 0.6 }}
    55	              className="zimm-focus-visible"
    56	              sx={{
    57	                transition:
    58	                  'color var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard), opacity var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard)',
    59	              }}
    60	            >
    61	              {props.linkText}
    62	            </Text>
    63	          )}
    64	        </Box>
    65	      ) : props.variant === 'breadcrumbs' ? (
    66	        <Box opacity={0.8}>{props.children}</Box>
    67	      ) : null}
    68	    </Box>
    69	  );
    70	};
    71	
    72	export { ZimmPageToolbar };
    73	export default ZimmPageToolbar;

