     1	/**
     2	 * Ambient module declarations for @salesforce/retail-react-app.
     3	 *
     4	 * This package ships without TypeScript types. We declare the modules we
     5	 * import in overrides/ with real types where we know the shape, and fall
     6	 * back to an untyped catch-all for everything else.
     7	 *
     8	 * Add specific declarations here as more subpaths are consumed in overrides/.
     9	 */
    10	
    11	declare module '@salesforce/retail-react-app/app/theme' {
    12	  import type { ChakraTheme } from '@chakra-ui/react';
    13	  const theme: ChakraTheme;
    14	  export default theme;
    15	}
    16	
    17	// Matches the pinned react-router-dom 5.3.4 (see package.json) — the package ships
    18	// without its own types and no @types/react-router-dom is installed, so this mirrors
    19	// that version's real shapes (history's Location/LocationDescriptor, match) rather
    20	// than a generic approximation.
    21	declare module 'react-router-dom' {
    22	  import type React from 'react';
    23	
    24	  interface Location<TState = unknown> {
    25	    pathname: string;
    26	    search: string;
    27	    hash: string;
    28	    state: TState;
    29	    key?: string;
    30	  }
    31	  export function useLocation<TState = unknown>(): Location<TState>;
    32	
    33	  // Every declared param is optional — a route pattern doesn't guarantee a segment
    34	  // was actually present in the matched URL. Default is `{}` in the real react-router
    35	  // types (so an unparameterised useParams()'s properties correctly fail to resolve);
    36	  // `NonNullable<unknown>` is the eslint-approved equivalent — our ban-types rule
    37	  // rejects a literal `{}`, and `Record<string, never>` was tried and rejected in
    38	  // review: it types every property as `never`, which is assignable to anything and
    39	  // so silently passes property access that should be a compile error.
    40	  export function useParams<TParams extends { [K in keyof TParams]?: string } = NonNullable<unknown>>(): TParams;
    41	
    42	  type To<TState = unknown> = string | { pathname?: string; search?: string; hash?: string; state?: TState };
    43	
    44	  interface LinkProps<TState = unknown> extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
    45	    to: To<TState>;
    46	    replace?: boolean;
    47	  }
    48	  export const Link: React.ForwardRefExoticComponent<LinkProps & React.RefAttributes<HTMLAnchorElement>>;
    49	
    50	  interface match<TParams extends { [K in keyof TParams]?: string } = NonNullable<unknown>> {
    51	    params: TParams;
    52	    isExact: boolean;
    53	    path: string;
    54	    url: string;
    55	  }
    56	
    57	  interface NavLinkProps extends LinkProps {
    58	    exact?: boolean;
    59	    activeClassName?: string;
    60	    activeStyle?: React.CSSProperties;
    61	    isActive?: (match: match | null, location: Location) => boolean;
